-- Rollback script generated by database-diff on <time>
-- Source (the sync script's model):  <server> / ddtest_ddlguard_inc_src
-- Target (will be changed back):     <server> / ddtest_ddlguard_inc_tgt (snapshot <time>)
--
-- Running this on the TARGET database after the sync script of the same comparison puts its
-- schema back as it was read during the comparison. REVIEW IT BEFORE RUNNING.
-- - Nothing in this file has been executed by database-diff.
-- - It assumes the target changed only through the sync script since the comparison.
-- - Database triggers (ON DATABASE) come first: the ones the sync script created or changed are
--   disabled, then dropped or put back. The ones that were enabled before the sync script
--   are enabled again by the last statements of this file: an enabled one fires on the
--   statements after it and may refuse them. If the script stops part way they stay
--   disabled: see the INCOMPLETE COMPARISON lines below for what to do then.
-- - Procedures, views, functions, triggers, synonyms, indexes and constraints the sync script
--   created are dropped next, with IF EXISTS so a sync script that stopped part way is fine.
-- - Tables, columns, sequences, types and schemas it created are commented out at the end:
--   dropping them loses the data written since.
-- - Changed objects get their earlier definition back. ALTER COLUMN statements are active:
--   check them for data loss (narrower types, NOT NULL). Except the change of a column that a
--   computed column uses: SQL Server refuses it (Msg 5074), so it is written as a group of
--   comments to run by hand (those computed columns dropped, the change, the columns added
--   again).
-- - A view that is altered back gets the indexes it had created again right after it (ALTER
--   VIEW drops every index of a view). The indexes of the other views come after the views.
-- - Objects only in the target are not here: the sync script leaves them (its drops are
--   commented out). Schemas, types and sequences it created only when missing are left in place.
-- - Only a backup brings back dropped data.
-- - Objects are ordered by kind, not by dependency; rerun a failed part after the rest.
-- - Uses CREATE OR ALTER and DROP IF EXISTS: SQL Server 2016 SP1 or later on the target.
-- - It starts with USE of the target database. If that fails (wrong server, no access), nothing
--   after it is executed, so no statement runs in another database.
-- - A changed index, constraint or default is dropped and created again in one transaction (a
--   default also around the type change of its column), under the SET XACT_ABORT ON below
--   (keep it when running only a part of this file): when a statement in it fails, the drop
--   is rolled back and the existing one stays.
-- - INCOMPLETE COMPARISON: the login that read the target has no VIEW DEFINITION permission, so
--   an object the sync script was to create may have been there before (its CREATE then
--   failed). The drops of procedures, views, functions, triggers and synonyms are therefore
--   commented out at the end: uncomment only those the sync script really created.
-- - Nor can this script tell which database triggers the sync script created. Each one that is
--   only in the source and enabled when this script starts is disabled first (it may refuse
--   the statements of this script), noted in a temporary table (#database_diff_disabled), and
--   enabled again by the last statements, after the commented-out drops. That also happens to
--   one that was there before the sync script: it ends as it started.
-- - If this script stops part way, those triggers stay disabled, the target's own among them,
--   and the notes are gone with the session. For each trigger it disables, the script prints
--   the statement that enables it again (USE ...; ENABLE TRIGGER ... ON DATABASE). Then: run
--   the script again to its end, and run those statements. Only a run in the same session
--   (query window) still has the notes and enables them itself; in another session the
--   script cannot know what the stopped run disabled. It prints a warning for each trigger it
--   finds disabled, also for one that was disabled all along: enable only what the stopped
--   run listed.
--
-- WARNING: Login <login> has no VIEW DEFINITION permission in target database ddtest_ddlguard_inc_tgt: objects it cannot access are invisible and definitions read as empty, so this comparison is incomplete.
USE [ddtest_ddlguard_inc_tgt];
GO
IF DB_ID(N'ddtest_ddlguard_inc_tgt') IS NULL OR DB_ID() <> DB_ID(N'ddtest_ddlguard_inc_tgt')
BEGIN
    RAISERROR(N'database-diff: cannot use database %s. The rest of this file is not executed.', 16, 1, N'ddtest_ddlguard_inc_tgt');
    SET NOEXEC ON;
END
GO
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
SET XACT_ABORT ON;
GO

-- ==========================================================================================
-- Database triggers first: disabled, then dropped or put back (enabled again by the last statements of this script)
-- ==========================================================================================
-- The comparison of the target is incomplete: this script cannot tell which of these the sync script created, and one that is enabled may refuse the statements below. The enabled ones are disabled, noted in a temporary table of this session, and enabled again by the last statements of this script.
IF OBJECT_ID(N'tempdb..#database_diff_disabled') IS NULL CREATE TABLE #database_diff_disabled (database_id int NOT NULL, name nvarchar(128) COLLATE Latin1_General_BIN2 NOT NULL);
GO
IF EXISTS (SELECT 1 FROM sys.triggers WHERE parent_class = 0 AND name = N'trAaa' AND is_disabled = 0) BEGIN INSERT INTO #database_diff_disabled (database_id, name) VALUES (DB_ID(), N'trAaa'); DISABLE TRIGGER [trAaa] ON DATABASE; PRINT N'database-diff: ' + QUOTENAME(DB_NAME()) + N': database trigger [trAaa] is disabled while this script runs; its last statements enable it again. If the script stops before them, run: USE ' + QUOTENAME(DB_NAME()) + N'; ENABLE TRIGGER [trAaa] ON DATABASE;'; END
GO
IF EXISTS (SELECT 1 FROM sys.triggers WHERE parent_class = 0 AND name = N'trBlock' AND is_disabled = 0) BEGIN INSERT INTO #database_diff_disabled (database_id, name) VALUES (DB_ID(), N'trBlock'); DISABLE TRIGGER [trBlock] ON DATABASE; PRINT N'database-diff: ' + QUOTENAME(DB_NAME()) + N': database trigger [trBlock] is disabled while this script runs; its last statements enable it again. If the script stops before them, run: USE ' + QUOTENAME(DB_NAME()) + N'; ENABLE TRIGGER [trBlock] ON DATABASE;'; END
GO
IF EXISTS (SELECT 1 FROM sys.triggers WHERE parent_class = 0 AND name = N'trHiddenOff' AND is_disabled = 0) BEGIN INSERT INTO #database_diff_disabled (database_id, name) VALUES (DB_ID(), N'trHiddenOff'); DISABLE TRIGGER [trHiddenOff] ON DATABASE; PRINT N'database-diff: ' + QUOTENAME(DB_NAME()) + N': database trigger [trHiddenOff] is disabled while this script runs; its last statements enable it again. If the script stops before them, run: USE ' + QUOTENAME(DB_NAME()) + N'; ENABLE TRIGGER [trHiddenOff] ON DATABASE;'; END
GO
IF EXISTS (SELECT 1 FROM sys.triggers WHERE parent_class = 0 AND name = N'trHiddenOn' AND is_disabled = 0) BEGIN INSERT INTO #database_diff_disabled (database_id, name) VALUES (DB_ID(), N'trHiddenOn'); DISABLE TRIGGER [trHiddenOn] ON DATABASE; PRINT N'database-diff: ' + QUOTENAME(DB_NAME()) + N': database trigger [trHiddenOn] is disabled while this script runs; its last statements enable it again. If the script stops before them, run: USE ' + QUOTENAME(DB_NAME()) + N'; ENABLE TRIGGER [trHiddenOn] ON DATABASE;'; END
GO
IF EXISTS (SELECT 1 FROM sys.triggers WHERE parent_class = 0 AND name = N'trNewOff' AND is_disabled = 0) BEGIN INSERT INTO #database_diff_disabled (database_id, name) VALUES (DB_ID(), N'trNewOff'); DISABLE TRIGGER [trNewOff] ON DATABASE; PRINT N'database-diff: ' + QUOTENAME(DB_NAME()) + N': database trigger [trNewOff] is disabled while this script runs; its last statements enable it again. If the script stops before them, run: USE ' + QUOTENAME(DB_NAME()) + N'; ENABLE TRIGGER [trNewOff] ON DATABASE;'; END
GO
IF EXISTS (SELECT 1 FROM sys.triggers WHERE parent_class = 0 AND name = N'trZeta' AND is_disabled = 0) BEGIN INSERT INTO #database_diff_disabled (database_id, name) VALUES (DB_ID(), N'trZeta'); DISABLE TRIGGER [trZeta] ON DATABASE; PRINT N'database-diff: ' + QUOTENAME(DB_NAME()) + N': database trigger [trZeta] is disabled while this script runs; its last statements enable it again. If the script stops before them, run: USE ' + QUOTENAME(DB_NAME()) + N'; ENABLE TRIGGER [trZeta] ON DATABASE;'; END
GO
-- Disabled before anything else: the sync script left them enabled, and an enabled one may refuse the statements of this script.
IF EXISTS (SELECT 1 FROM sys.triggers WHERE parent_class = 0 AND name = N'trOld') DISABLE TRIGGER [trOld] ON DATABASE;
GO
-- trOld (database trigger): Definition differs
GO
CREATE OR ALTER TRIGGER trOld ON DATABASE FOR CREATE_SYNONYM AS BEGIN SET NOCOUNT ON; END

GO

-- ==========================================================================================
-- Created by the sync script: dropped
-- ==========================================================================================
DROP INDEX IF EXISTS [IX_Items_Name] ON [dbo].[Items];
GO

