GO
IF EXISTS (SELECT 1 FROM #database_diff_disabled WHERE database_id = DB_ID() AND name = N'trBlock') AND EXISTS (SELECT 1 FROM sys.triggers WHERE parent_class = 0 AND name = N'trBlock') ENABLE TRIGGER [trBlock] ON DATABASE;
IF EXISTS (SELECT 1 FROM sys.triggers WHERE parent_class = 0 AND name = N'trBlock' AND is_disabled = 1) AND NOT EXISTS (SELECT 1 FROM #database_diff_disabled WHERE database_id = DB_ID() AND name = N'trBlock') PRINT N'database-diff: ' + QUOTENAME(DB_NAME()) + N': WARNING: database trigger [trBlock] is disabled, and this run did not disable it. It may have been disabled all along. If an earlier run of this script stopped part way, the lines that run printed list what it disabled: only if this trigger is among them, run: USE ' + QUOTENAME(DB_NAME()) + N'; ENABLE TRIGGER [trBlock] ON DATABASE;';
GO
