GO
IF EXISTS (SELECT 1 FROM #database_diff_disabled WHERE database_id = DB_ID() AND name = N'trHiddenOn') AND EXISTS (SELECT 1 FROM sys.triggers WHERE parent_class = 0 AND name = N'trHiddenOn') ENABLE TRIGGER [trHiddenOn] ON DATABASE;
IF EXISTS (SELECT 1 FROM sys.triggers WHERE parent_class = 0 AND name = N'trHiddenOn' AND is_disabled = 1) AND NOT EXISTS (SELECT 1 FROM #database_diff_disabled WHERE database_id = DB_ID() AND name = N'trHiddenOn') PRINT N'database-diff: ' + QUOTENAME(DB_NAME()) + N': WARNING: database trigger [trHiddenOn] is disabled, and this run did not disable it. It may have been disabled all along. If an earlier run of this script stopped part way, the lines that run printed list what it disabled: only if this trigger is among them, run: USE ' + QUOTENAME(DB_NAME()) + N'; ENABLE TRIGGER [trHiddenOn] ON DATABASE;';
GO
IF EXISTS (SELECT 1 FROM #database_diff_disabled WHERE database_id = DB_ID() AND name = N'trNewOff') AND EXISTS (SELECT 1 FROM sys.triggers WHERE parent_class = 0 AND name = N'trNewOff') ENABLE TRIGGER [trNewOff] ON DATABASE;
IF EXISTS (SELECT 1 FROM sys.triggers WHERE parent_class = 0 AND name = N'trNewOff' AND is_disabled = 1) AND NOT EXISTS (SELECT 1 FROM #database_diff_disabled WHERE database_id = DB_ID() AND name = N'trNewOff') PRINT N'database-diff: ' + QUOTENAME(DB_NAME()) + N': WARNING: database trigger [trNewOff] is disabled, and this run did not disable it. It may have been disabled all along. If an earlier run of this script stopped part way, the lines that run printed list what it disabled: only if this trigger is among them, run: USE ' + QUOTENAME(DB_NAME()) + N'; ENABLE TRIGGER [trNewOff] ON DATABASE;';
GO
IF EXISTS (SELECT 1 FROM #database_diff_disabled WHERE database_id = DB_ID() AND name = N'trZeta') AND EXISTS (SELECT 1 FROM sys.triggers WHERE parent_class = 0 AND name = N'trZeta') ENABLE TRIGGER [trZeta] ON DATABASE;
IF EXISTS (SELECT 1 FROM sys.triggers WHERE parent_class = 0 AND name = N'trZeta' AND is_disabled = 1) AND NOT EXISTS (SELECT 1 FROM #database_diff_disabled WHERE database_id = DB_ID() AND name = N'trZeta') PRINT N'database-diff: ' + QUOTENAME(DB_NAME()) + N': WARNING: database trigger [trZeta] is disabled, and this run did not disable it. It may have been disabled all along. If an earlier run of this script stopped part way, the lines that run printed list what it disabled: only if this trigger is among them, run: USE ' + QUOTENAME(DB_NAME()) + N'; ENABLE TRIGGER [trZeta] ON DATABASE;';
